#!/usr/bin/env bash
# Reproduce R5 v2x-track submission 'r5' (model-v2x-track/routed-g7): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-v2x-track/routed-g7/submissions/2026-10-14_r5/v2x_r5_submission.zip (md5 0d339f79a21059a8c97211d4d7c15533).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g7/test/reproduce_r5.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-v2x-track/routed-g7/test/output/repro_r5
mkdir -p $OUT
# member pvros4s2_tta: model-v2x-track/pvrcnnpp-ros-g1v4-s2, checkpoint md5 30b8d6036c6f2c4b8d9de562d0f2e6a5
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v4-s2 --ckpt model-v2x-track/pvrcnnpp-ros-g1v4-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-ros-g1v4-s2/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros4s2_tta.json
# member pvros_tta: model-v2x-track/pvrcnnpp-ros-g1v3, checkpoint md5 eea352738f9a0d47a55b617828f46d01
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v3 --ckpt model-v2x-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros_tta.json
# member ut_tta: model-v2x-track/pointpillars-ut, checkpoint md5 2081ca05e3326bfdbf27794239cdf172
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-ut --ckpt model-v2x-track/pointpillars-ut/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-ut/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_ut_tta.json
# member vrros4_tta: model-v2x-track/voxelrcnn-ros-g1v4, checkpoint md5 b85264eaec17f167f34b0185acce9313
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v4 --ckpt model-v2x-track/voxelrcnn-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros4_tta.json
# member vrros4s2_tta: model-v2x-track/voxelrcnn-ros-g1v4-s2, checkpoint md5 501843304886fa1122aa790f76c2a943
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v4-s2 --ckpt model-v2x-track/voxelrcnn-ros-g1v4-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v4-s2/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros4s2_tta.json
# member vrros5_tta: model-v2x-track/voxelrcnn-ros-g1v5, checkpoint md5 a90a13b7e29706bb06b8a435bf0b3eac
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v5 --ckpt model-v2x-track/voxelrcnn-ros-g1v5/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v5/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros5_tta.json
# member vrros_tta: model-v2x-track/voxelrcnn-ros-g1v3, checkpoint md5 5677c039b8cc33a058b045f732c687de
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v3 --ckpt model-v2x-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros_tta.json
python common/tools/route_predictions.py merge model-v2x-track/routed-g7 --pred pvros4s2_tta=$OUT/predictions_pvros4s2_tta.json --pred pvros_tta=$OUT/predictions_pvros_tta.json --pred ut_tta=$OUT/predictions_ut_tta.json --pred vrros4_tta=$OUT/predictions_vrros4_tta.json --pred vrros4s2_tta=$OUT/predictions_vrros4s2_tta.json --pred vrros5_tta=$OUT/predictions_vrros5_tta.json --pred vrros_tta=$OUT/predictions_vrros_tta.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-v2x-track/routed-g7 --tag r5 --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v5/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-g7/submissions/2026-10-14_r5/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-g7/submissions/2026-10-14_r5/v2x_r5_submission.zip --syn-list model-v2x-track/routed-g7/submissions/2026-10-14_r5/synthetic_ids.txt); fi
python common/tools/package_submission.py model-v2x-track/routed-g7 --tag repro-r5 --pred $OUT/predictions.json --synthetic pcdet/g1-v5 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of r5' --reproduction
Z=model-v2x-track/routed-g7/test/output/repro-r5/submission.zip
python common/tools/check_submission.py --track v2x $Z --official
python common/tools/reproduce_submission.py model-v2x-track/routed-g7 --tag r5 --compare-zip $Z     # predictions and frames against the scored zip
